llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C56"],
      "claim": "Dideoxycytidine, a very polar pyrimidine nucleoside analog, had absolute oral bioavailability of 77–88% in patients, demonstrating that hydrophilic nucleosides can be well absorbed and exceed the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C63"],
      "claim": "Lamivudine, another polar nucleoside reverse-transcriptase inhibitor, showed absolute oral bioavailability of 87% in adults, supporting high oral bioavailability for the query nucleoside.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "Zidovudine, a polar azido nucleoside, had oral bioavailability around 63–68%, still well above 20%, indicating that nucleoside transporters can overcome poor passive permeability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C39"],
      "claim": "Rufinamide, a carboxamide-containing heteroaromatic with the highest transfer score, had 85% oral bioavailability, showing that the carboxamide and polar functionality in the query does not preclude high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "Didanosine, a dideoxypurine nucleoside, gave F values as low as 19% in children, the main contradictory evidence; however, its poor F is largely attributed to acid lability and degradation, which is less applicable to the stable full riboside AICAR.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The weight of high-transfer experimental evidence from polar nucleoside analogs (ddC, lamivudine, zidovudine) and carboxamide-containing drugs supports F ≥ 20% for AICAR. The only low-F nucleoside anchor, didanosine, is acid-labile and less transferable to this stable riboside. The unfavorable physicochemical prior is overridden by transporter-mediated absorption evidence.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for AICAR/acadesine in humans.",
    "Didanosine's low F is confounded by acid lability and pediatric dosing; its relevance to the stable riboside AICAR is uncertain.",
    "Intestinal nucleoside transporter substrate status of AICAR is inferred rather than directly evidenced."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

